    // Fallback: parse from regexp
    const src = String(layer?.regexp || '');
    // Typical: /^\/api\/v1\/users\/?(?=\/|$)/i
    const match = src.match(/^\/\^\\\/(.*)\\\/\?\(\?\=\\\/\|\$\)\/i$/);
    if (match && match[1]) {
        return '/' + match[1].replace(/\\\//g, '/');
    }

    return '';
